72: // Helper: Retry dengan exponential backoff untuk error sementara (503, 429, dll)
73: async function retryWithBackoff(fn, maxRetries = 3, baseDelay = 2000) {
74:   for (let attempt = 0; attempt <= maxRetries; attempt++) {
75:     try {
76:       return await fn();
77:     } catch (error) {
78:       const status = error?.status;
79:       const isRetryable = [429, 500, 503].includes(status);
